import {W,H} from './model.js';
export function render(ctx,m,selection=-1){ctx.clearRect(0,0,W,H);ctx.fillStyle='#fafbf9';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#dde2dc';ctx.lineWidth=1;
 for(let x=0;x<=W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<=H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
 ctx.font='14px system-ui';ctx.fillStyle='#59645d';ctx.fillText('x →  ·  y ↓  ·  800 × 400 логических px',18,25);
 if(m.id===11){circuit(ctx,m);return;}
 if(m.id===13){ctx.fillStyle='#e8f0e880';ctx.fillRect(0,40,350,360);ctx.fillStyle='#eceaf180';ctx.fillRect(450,40,350,360);ctx.fillStyle='#59645d';ctx.fillText('Притяжение',35,60);ctx.fillText('Сопротивление',345,60);ctx.fillText('Отталкивание',620,60);}
 if(m.id===12){const {x,y}=m.target;const g=ctx.createRadialGradient(x,y,5,x,y,170);g.addColorStop(0,'#b8cdb580');g.addColorStop(1,'#b8cdb500');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#879f84';for(let a=0;a<Math.PI*2;a+=Math.PI/6){const sx=x+Math.cos(a)*110,sy=y+Math.sin(a)*110,ex=x+Math.cos(a)*40,ey=y+Math.sin(a)*40;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ex,ey);ctx.stroke();}ctx.fillStyle='#3d5938';ctx.fillText('Условный максимум B²',Math.min(x+12,600),Math.max(70,y-20));}
 if([1,2,12,13].includes(m.id)){ctx.strokeStyle='#496553';ctx.beginPath();ctx.moveTo(m.target.x-9,m.target.y);ctx.lineTo(m.target.x+9,m.target.y);ctx.moveTo(m.target.x,m.target.y-9);ctx.lineTo(m.target.x,m.target.y+9);ctx.stroke();}
 if([10,14].includes(m.id)){ctx.strokeStyle='#536c52';ctx.lineWidth=2;ctx.strokeRect(680,220,60,60);ctx.fillStyle='#40593f';ctx.fillText('ЦЕЛЬ',685,210);}
 ctx.strokeStyle='#809b8b80';ctx.lineWidth=2;ctx.beginPath();m.trail.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();
 for(const [i,l] of m.links.entries()){const a=m.balls[l.a],b=m.balls[l.b];ctx.setLineDash(l.type==='soft'?[5,5]:[]);ctx.strokeStyle=i===selection?'#8a552d':'#6a7f72';ctx.lineWidth=i===selection?4:2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#485c4e';ctx.fillText(`${i+1} · ${l.type==='soft'?'М':'Ж'}`,(a.x+b.x)/2+5,(a.y+b.y)/2-5);}
 m.balls.forEach((b,i)=>{ctx.fillStyle=b.fixed?'#68716b':i===0?'#3f6655':'#e2e8df';ctx.strokeStyle='#40554a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=b.fixed||i===0?'white':'#304638';ctx.textAlign='center';ctx.fillText(b.fixed?'×':String(i+1),b.x,b.y+5);ctx.textAlign='left';});
 if(m.id===1){const b=m.balls[0];ctx.fillStyle='#394b40';ctx.fillText(`x=${Math.round(b.x)}, y=${Math.round(b.y)}`,Math.min(b.x+25,620),Math.max(50,b.y-20));}
 if(m.drag && [10,14].includes(m.id)){const d=m.drag;ctx.strokeStyle='#866244';ctx.beginPath();ctx.moveTo(d.anchor.x,d.anchor.y);ctx.lineTo(d.pointer.x,d.pointer.y);ctx.stroke();ctx.setLineDash([3,7]);ctx.beginPath();const vx=Math.max(-900,Math.min(900,(d.anchor.x-d.pointer.x)*m.params.power)),vy=Math.max(-900,Math.min(900,(d.anchor.y-d.pointer.y)*m.params.power));for(let t=0;t<=1.5;t+=.04){const x=d.anchor.x+vx*t,y=d.anchor.y+vy*t+.5*m.params.gravity*t*t;t?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();ctx.setLineDash([]);}
}
function circuit(c,m){c.fillStyle='#243e33';c.fillRect(110,75,580,260);c.strokeStyle='#b9aa66';c.lineWidth=8;const points=[[180,260],[180,135],[340,135],[450,135],[620,135],[620,260],[180,260]];c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();c.fillStyle='#e2ded0';c.fillRect(335,119,120,32);c.fillStyle='#243e33';c.font='14px system-ui';c.fillText(`${m.params.resistance} Ω`,355,141);c.strokeStyle='#eef0e8';c.lineWidth=3;c.beginPath();c.moveTo(164,235);c.lineTo(196,235);c.moveTo(171,245);c.lineTo(189,245);c.stroke();c.fillStyle='#e6eadf';c.fillText(`${m.params.voltage} V`,205,250);c.fillStyle='#243e33';c.fillRect(490,245,55,30);c.strokeStyle='#ece4af';c.beginPath();c.moveTo(490,260);c.lineTo(545,m.closed?260:235);c.stroke();const current=m.current();
 if(current>0){const length=1130;for(let n=0;n<12;n++){let d=(n*length/12+m.time*current*1200)%length;for(let i=0;i<points.length-1;i++){const [x,y]=points[i],[xx,yy]=points[i+1],len=Math.hypot(xx-x,yy-y);if(d<=len){c.fillStyle='#f5e4a0';c.beginPath();c.arc(x+(xx-x)*d/len,y+(yy-y)*d/len,3,0,7);c.fill();break;}d-=len;}}}
 c.fillStyle='#334b3e';c.fillText(`I = ${(current*1000).toFixed(1)} mA · P = ${(current*m.params.voltage).toFixed(3)} W · ${m.closed?'замкнуто':'разомкнуто'}`,130,370);
}
